rcore 1;
package `terminalSpellings` version "1";
metamodel "urn:intersect:xtext:mini-kerml:terminal-spellings:1" prefix `k` {
  class `Model` {
    attr `name`: EString [0,1];
    ref `members`: external "#//@eClassifiers.1" [0,*] containment;
  }
  abstract class `Element` {
    attr `name`: EString [0,1] unsettable;
  }
  class `Type` extends external "#//@eClassifiers.1" {
    attr `isAbstract`: EBoolean [0,1] unsettable;
  }
  class `Feature` extends external "#//@eClassifiers.1" {
    ref `target`: external "#//@eClassifiers.2" [0,1] unsettable;
  }
}

grammar audit.scopes.FragmentInternalSignificance hidden(WS,ML_COMMENT,SL_COMMENT)
import "urn:intersect:xtext:mini-kerml:terminal-spellings:1" as k
import "http://www.eclipse.org/emf/2002/Ecore" as ecore
Model returns k::Model: {k::Model} '[' Fields ']' 'done';
fragment Fields returns k::Model hidden(): name=ID ':' ID;
terminal ID returns ecore::EString: ('a'..'z'|'\u00e9')+;
terminal WS returns ecore::EString: (' '|'\t'|'\r'|'\n')+;
terminal ML_COMMENT returns ecore::EString: '/*' ->'*/';
terminal SL_COMMENT returns ecore::EString: '//' !('\n'|'\r')* ('\r'? '\n')?;

